#!/usr/bin/env node
/**
 * Uploads the unit-exam paper (questions only) straight into Supabase.
 *
 *   node scripts/unit-exam-paper-upload.mjs            → upload + verify
 *   node scripts/unit-exam-paper-upload.mjs --cleanup  → also delete test attempts (phones in TEST_PHONES)
 *
 * The alternative to pasting .private/unit-exam-paper.sql by hand. It reads the
 * service key through Next's own env loader — the same variables `next dev`
 * uses — and prints only counts, never the key. The paper never passes through
 * git: it comes from `.private/` (generated by make-exam-web.py in mr-anas-hq).
 */
import { readFileSync } from 'node:fs'
import { argv, exit } from 'node:process'
import nextEnv from '@next/env'
import { createClient } from '@supabase/supabase-js'

nextEnv.loadEnvConfig(process.cwd())

const url =
  process.env.SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL || 'https://rhrwuqjkqflceuddfsso.supabase.co'
const key = ['SUPABASE_SERVICE_ROLE_KEY', 'SUPABASE_SERVICE_KEY', 'SUPABASE_SECRET_KEY', 'SUPABASE_SECRET', 'SUPABASE_KEY']
  .map((n) => process.env[n]?.trim())
  .find(Boolean)
if (!key) {
  console.error('FAIL: no Supabase service key in the local environment.')
  exit(1)
}

const TEST_PHONES = ['01099999999', '01155555555', '01288888888', '01577777777', '01000000001']

const paper = JSON.parse(readFileSync('.private/unit-1-exam.public.json', 'utf-8'))
const text = JSON.stringify(paper)
for (const k of ['"answer"', '"model"', '"rubric"', '"cells"', '"slot"']) {
  if (text.includes(k)) {
    console.error(`FAIL: the paper contains ${k} — refusing to upload.`)
    exit(1)
  }
}

const db = createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } })

const up = await db.from('unit_exam_papers').upsert({ slug: paper.slug, paper, updated_at: new Date().toISOString() })
if (up.error) {
  console.error('FAIL upload:', up.error.message)
  exit(1)
}

const check = await db.from('unit_exam_papers').select('slug, paper, updated_at').eq('slug', paper.slug).single()
if (check.error) {
  console.error('FAIL verify:', check.error.message)
  exit(1)
}
console.log(`paper: ${check.data.slug} · ${check.data.paper.items.length} questions + bonus · ${check.data.updated_at}`)

for (const t of ['unit_exam_attempts', 'unit_exam_answers', 'unit_exam_events', 'unit_exam_extensions']) {
  const r = await db.from(t).select('*', { count: 'exact', head: true })
  console.log(`${t}: ${r.error ? 'ERROR ' + r.error.message : r.count + ' rows'}`)
}

if (argv.includes('--cleanup')) {
  const del = await db.from('unit_exam_attempts').delete().eq('exam_slug', paper.slug).in('phone', TEST_PHONES).select('id')
  console.log(del.error ? `cleanup FAIL: ${del.error.message}` : `cleanup: deleted ${del.data.length} test attempt(s)`)
}
